 function currentView(name){document.body.classList.toggle('dashboard-active',name==='dashboard');document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==`view-${name}`));document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const label={dashboard:'Dashboard',cultivations:'Farms & cultivations',expenses:'Expenses',income:'Income & profit',reports:'Reports',calendar:'Farm Work Calendar',settings:'Settings & backup'}[name];$('crumb').textContent=label;$('page-title').innerHTML=name==='dashboard'?`Good day, ${esc(settings.owner||'Suranga')} <span class="sun">☀</span>`:label;$('page-subtitle').textContent={dashboard:'A clear picture of how your farm is growing.',cultivations:'Organize your land, crops and seasons.',expenses:'Record spending and see where each rupee goes.',income:'Track farm sales and estimated profit.',reports:'Useful summaries for your fields and seasons.',calendar:'Plan and review work by date and cultivation.',settings:'Manage your farm details and keep a safe copy of your data.'}[name];history.replaceState(null,'',`#${name}`);window.scrollTo({top:0,behavior:'smooth'});}
 function calendarDate(value){const [y,m,d]=String(value||dateNow()).split('-').map(Number);return new Date(y,m-1,d);}
 function calendarISO(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
