 function calendarLabel(date,withWeekday=false){return `${withWeekday?calendarWeekdays[date.getDay()]+' · ':''}${date.getDate()} ${calendarMonths[date.getMonth()]} ${date.getFullYear()}`;}
 function calendarEventsForDate(date){const cultivation=$('calendar-cultivation-filter').value;return calendarEvents.filter(event=>event.date===date&&(cultivation==='all'||event.cultivationId===cultivation)).sort((a,b)=>(a.time||'').localeCompare(b.time||'')||Number(a.createdAt||0)-Number(b.createdAt||0));}
 function calendarFarmLabel(event){const farm=farmFor(event.cultivationId);return farm?`${farm.name} · ${cropName(farm)}`:event.cultivationId?'Cultivation unavailable':'No cultivation';}
 function renderCalendar(){if(!$('calendar-grid'))return;setSelect('calendar-cultivation-filter',farms,'All cultivations',farm=>`${cropName(farm)} — ${farm.batch||'Season unspecified'} · ${farm.name}`);setSelect('calendar-event-cultivation',farms,'No cultivation',farm=>`${cropName(farm)} — ${farm.batch||'Season unspecified'} · ${farm.name}`);const selected=calendarDate(calendarSelectedDate),weekdayNames=['සඳු','අඟ','බදා','බ්‍රහ','සිකු','සෙන','ඉරි'],filtered=calendarEvents.filter(event=>$('calendar-cultivation-filter').value==='all'||event.cultivationId===$('calendar-cultivation-filter').value),period=$('calendar-period-title'),grid=$('calendar-grid');$('calendar-date-select').value=calendarSelectedDate;$('calendar-selected-heading').textContent=calendarLabel(selected);document.querySelectorAll('[data-calendar-mode]').forEach(button=>button.classList.toggle('active',button.dataset.calendarMode===calendarMode));
  if(calendarMode==='day'){period.textContent=calendarLabel(selected,true);grid.className='calendar-grid calendar-day-focus';grid.innerHTML=`<div class="calendar-focus-date"><span>${esc(calendarWeekdays[selected.getDay()])}</span><b>${selected.getDate()}</b><small>${esc(calendarMonths[selected.getMonth()])} ${selected.getFullYear()}</small></div>`;}
  else{let start;if(calendarMode==='month'){period.textContent=`${calendarMonths[selected.getMonth()]} ${selected.getFullYear()}`;start=new Date(selected.getFullYear(),selected.getMonth(),1);start.setDate(start.getDate()-(start.getDay()+6)%7);}else{start=new Date(selected);start.setDate(start.getDate()-(start.getDay()+6)%7);const end=new Date(start);end.setDate(end.getDate()+6);period.textContent=`${calendarLabel(start)} – ${calendarLabel(end)}`;}const count=calendarMode==='month'?42:7;grid.className=`calendar-grid calendar-${calendarMode}`;grid.innerHTML=weekdayNames.map(name=>`<div class="calendar-weekday">${esc(name)}</div>`).join('')+Array.from({length:count},(_,i)=>{const date=new Date(start);date.setDate(start.getDate()+i);const iso=calendarISO(date),items=filtered.filter(event=>event.date===iso),outside=calendarMode==='month'&&date.getMonth()!==selected.getMonth();return `<button type="button" class="calendar-date-cell${outside?' is-outside':''}${iso===calendarSelectedDate?' is-selected':''}${iso===dateNow()?' is-today':''}" data-calendar-date="${iso}" aria-label="${esc(calendarLabel(date,true))} · ${items.length} ${esc(window.FarmBookSinhala?.translate('entries')||'entries')}"><span class="calendar-date-number">${date.getDate()}</span><span class="calendar-cell-events">${items.slice(0,calendarMode==='month'?2:4).map(event=>`<span class="calendar-event-chip">${event.time?esc(event.time)+' · ':''}${esc(event.title)}</span>`).join('')}${items.length>(calendarMode==='month'?2:4)?`<small class="calendar-more">+${items.length-(calendarMode==='month'?2:4)} ${esc(window.FarmBookSinhala?.translate('more')||'more')}</small>`:''}</span><span class="calendar-entry-dot" aria-hidden="true">${items.length||''}</span></button>`;}).join('');}
  const entries=calendarEventsForDate(calendarSelectedDate);$('calendar-entry-count').textContent=entries.length;$('calendar-day-entries').innerHTML=entries.length?entries.map(event=>`<article class="calendar-entry"><div class="calendar-entry-time">${event.time?esc(event.time):'<span class="calendar-no-time">All day</span>'}</div><div class="calendar-entry-copy"><b>${esc(event.title)}</b><small>${esc(calendarFarmLabel(event))} · ${esc(window.FarmBookSinhala?.translate(event.category)||event.category)}</small>${event.notes?`<p>${esc(event.notes)}</p>`:''}</div><div class="calendar-entry-actions"><button type="button" class="icon-btn" data-calendar-edit="${esc(event.id)}" aria-label="Edit calendar entry">✎</button><button type="button" class="icon-btn danger" data-calendar-delete="${esc(event.id)}" aria-label="Delete calendar entry">×</button></div></article>`).join(''):'<div class="calendar-empty"><span aria-hidden="true">▦</span><p>No farm work recorded for this date.</p></div>';}
 function openCalendarEvent(event){$('calendar-event-form').reset();$('calendar-event-id').value=event?.id||'';$('calendar-event-cultivation').value=event?.cultivationId||'';$('calendar-event-title').value=event?.title||'';$('calendar-event-date').value=event?.date||calendarSelectedDate;$('calendar-event-time').value=event?.time||'';$('calendar-event-category').value=event?.category||'Field work';$('calendar-event-notes').value=event?.notes||'';$('calendar-form-title').textContent=event?'Edit farm work':'Add farm work';$('calendar-save').textContent=event?'Update farm work':'Save farm work';$('calendar-event-card').classList.remove('hidden');$('calendar-event-card').scrollIntoView({behavior:'smooth',block:'center'});}
 function shiftCalendar(delta){const date=calendarDate(calendarSelectedDate);if(calendarMode==='day')date.setDate(date.getDate()+delta);else if(calendarMode==='week')date.setDate(date.getDate()+delta*7);else{const day=date.getDate(),target=new Date(date.getFullYear(),date.getMonth()+delta,1);target.setDate(Math.min(day,new Date(target.getFullYear(),target.getMonth()+1,0).getDate()));date.setTime(target.getTime());}calendarSelectedDate=calendarISO(date);renderCalendar();}
 function expenseMatches(r){const search=$('search').value.trim().toLowerCase(),farm=$('filter-farm').value,crop=$('filter-crop').value,cat=$('filter-category').value,batch=$('filter-batch').value,from=$('filter-from').value,to=$('filter-to').value,f=farmFor(r.farmId);const hay=[r.work,r.description,r.category,f?.name,cropName(f),r.crop,r.batch].join(' ').toLowerCase();return(!search||hay.includes(search))&&(farm==='all'||r.farmId===farm)&&(crop==='all'||(f&&f.id===crop))&&(cat==='all'||r.category===cat)&&(batch==='all'||r.batch===batch)&&(!from||r.date>=from)&&(!to||r.date<=to);}
