 function expCard(r){return `<article class="record-card"><div class="record-card-top"><b>${esc(r.work)}</b><span>${esc(dateText(r.date))}</span></div><p>${esc(farmLabel(r.farmId))}${r.batch?' · '+esc(r.batch):''}</p><p>${esc(r.category)}${r.description?' · '+esc(r.description):''}</p><div class="record-card-bottom"><span>${esc(r.quantity)} ${esc(r.unit)} · <b>${cash(r.total)}</b></span><span class="actions"><button class="icon-btn" data-action="edit-expense" data-id="${esc(r.id)}">✎</button><button class="icon-btn danger" data-action="delete-expense" data-id="${esc(r.id)}">×</button></span></div></article>`;}
 function renderExpenses(){const list=expenses.filter(expenseMatches).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt);$('records-body').innerHTML=list.map(expRow).join('');$('mobile-records').innerHTML=list.map(expCard).join('');$('expense-count').textContent=list.length;$('filtered-label').textContent=`Showing ${list.length} of ${expenses.length} records`;$('expense-empty').classList.toggle('hidden',list.length>0);}
 const catTotals=cat=>sum(expenses.filter(e=>e.category===cat));
 function dashboardFarmScope(){const id=$('dashboard-cultivation-select')?.value;return id&&id!=='all'?farmFor(id):null;}
