 function cropPhoto(f){const crop=String(cropName(f)||'').trim().toLocaleLowerCase();if(/chilli|chili|මිරිස්/.test(crop))return './assets/crop-chilli.jpg';if(/tomato|තක්කාලි/.test(crop))return './assets/crop-tomato.jpg';if(/paddy|rice|වී|සහල්/.test(crop))return './assets/hero-rice-field.jpg';if(/banana|කෙසෙල්/.test(crop))return './assets/crop-banana.jpg';if(/cucumber|පිපිඤ්ඤා/.test(crop))return './assets/crop-cucumber.jpg';if(/bitter\s*gourd|කරවිල/.test(crop))return './assets/crop-bitter-gourd.jpg';if(/ridge\s*gourd|වැටකොළු/.test(crop))return './assets/crop-ridge-gourd.jpg';if(/radish|රාබු/.test(crop))return './assets/crop-radish.jpg';if(/capsicum|මාළු\s*මිරිස්/.test(crop))return './assets/crop-capsicum.jpg';if(/pumpkin|වට්ටක්කා/.test(crop))return './assets/crop-pumpkin.jpg';if(/papaya|පැපොල්/.test(crop))return './assets/crop-papaya.png';return './assets/crop-generic.jpg';}
 function renderMyCultivations(){const list=$('dashboard-cultivations');if(!list)return;const heading=list.previousElementSibling,selected=dashboardFarmScope(),visible=selected?[selected]:farms;if(heading){const eyebrow=heading.querySelector('.eyebrow'),title=heading.querySelector('h2');if(eyebrow)eyebrow.textContent=visible.length?'BY FIELD & CROP':'AVAILABLE CROPS';if(title)title.textContent=visible.length?'My Cultivations':'Supported crops';}list.classList.add('dashboard-cultivation-list');if(!visible.length){const gallery=[...$('farm-crop').options].map(o=>o.value).filter(Boolean);list.innerHTML='<div class="dashboard-crop-catalog">'+gallery.map(c=>'<article class="dashboard-catalog-card"><img class="dashboard-crop-image" src="'+cropPhoto({crop:c})+'" alt="" loading="lazy"><b>'+esc(dashboardCropLabel({crop:c}))+'</b></article>').join('')+'</div><p class="dashboard-empty-hint">No cultivation records yet. These are supported crop types.</p><button type="button" class="primary-btn dashboard-catalog-add" data-action="new-cultivation-from-gallery">＋ Add a cultivation</button>';return;}list.innerHTML=visible.map(f=>{const cropLabel=dashboardCropLabel(f),seasonLabel=f.batch||window.FarmBookSinhala?.translate('Season unspecified')||'Season unspecified',areaUnit=window.FarmBookSinhala?.translate(f.areaUnit||'Acre')||f.areaUnit||'Acre',ownExpenses=expenses.filter(r=>r.farmId===f.id),ownIncome=incomes.filter(r=>r.farmId===f.id),expenseTotal=sum(ownExpenses),incomeTotal=sum(ownIncome),result=incomeTotal-expenseTotal,completed=f.status==='completed';return '<article class="farm-card dashboard-farm-card"><img class="dashboard-crop-image" src="'+cropPhoto(f)+'" alt="" loading="lazy"><div class="dashboard-farm-content"><div class="dashboard-farm-heading"><div><b>'+esc(cropLabel)+' — '+esc(seasonLabel)+'</b><small>Farm: '+esc(f.name)+'</small></div><span class="badge">'+(completed?'Completed':'Active')+'</span></div><div class="dashboard-farm-area">'+(f.area?esc(f.area)+' '+esc(areaUnit):'Area not set')+'</div><div class="dashboard-farm-finance"><div><small>EXPENSES</small><b>'+cash(expenseTotal)+'</b></div><div><small>INCOME</small><b>'+cash(incomeTotal)+'</b></div><div><small>PROFIT / LOSS</small><b>'+cash(result)+'</b></div></div><button type="button" class="secondary-btn" data-action="dashboard-view-cultivation" data-id="'+esc(f.id)+'">View cultivation</button></div></article>';}).join('');}
 function renderDashboardActivity(){const target=$('dashboard-recent-activity');if(!target)return;const entries=[...dashboardScoped(expenses).map(r=>({type:'expense',date:r.date||'',createdAt:Number(r.createdAt||0),description:r.work||r.description||'වියදම',detail:[r.description,r.category?window.FarmBookSinhala?.translate(r.category):''].filter(Boolean).join(' · '),farm:dashboardFarmLabel(r.farmId),total:Number(r.total||0)})),...dashboardScoped(incomes).map(r=>({type:'income',date:r.date||'',createdAt:Number(r.createdAt||0),description:r.description||'ආදායම',detail:'ආදායම්',farm:dashboardFarmLabel(r.farmId),total:Number(r.total||0)}))].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt).slice(0,5);target.innerHTML=entries.length?entries.map(r=>'<article class="activity-item"><span class="activity-icon '+r.type+'">'+(r.type==='income'?'↗':'↘')+'</span><div class="activity-copy"><b>'+esc(r.description)+'</b><small>'+esc(r.farm)+' · '+esc(r.detail)+'</small></div><div class="activity-value"><small>'+esc(dateText(r.date))+'</small><b class="'+r.type+'">'+cash(r.total)+'</b></div></article>').join(''):'<div class="activity-empty">තවම මෑත වාර්තා නැත.</div>';}
